        'Shipped': {'deliver'}, 
        'Created': {'cancel'}, 
        'Accepted': {'cancel'}, 
        'Packed': {'cancel'}
    }
    if current_state in transitions and event in transitions[current_state]:
        if current_state == 'Created' and event == 'confirm':
            return 'Accepted'
        elif current_state == 'Accepted' and event == 'pack':
            return 'Packed'
        elif current_state == 'Packed' and event == 'ship':
            return 'Shipped'
        elif current_state == 'Shipped' and event == 'deliver':
            return 'Delivered'
        elif event == 'cancel':
            return 'Cancelled'
    return None

