def emi(P, annual_rate, months):
    if annual_rate == 0:
        return round(P / months, 2)
    monthly_rate = annual_rate / 100 / 12
    numerator = P * monthly_rate * (1 + monthly_rate) ** months
    denominator = (1 + monthly_rate) ** months - 1
    emi = round(numerator / denominator, 2)
    return emi

